<div class="ops-card-head"><strong>#{{ $order->id }}</strong>@include('operations.channel')<span>{{ App\Support\OrderMode::label($order->mode,$order->dining_label) }}</span></div>
<div class="ops-card-meta"><span>{{ $order->mode==='dine_in'?($order->dining_label??'Salão'):(preg_split('/\s+/u',trim($order->customer_name))[0]??'Cliente') }}</span><small>{{ $stores->firstWhere('id',$order->store_id)?->name }}</small></div>
