<div class="ops-items">@foreach($board['items']->get($order->id,collect()) as $item)<div><strong>{{ $item->quantity }}× {{ $item->name }}</strong>@foreach(json_decode($item->options??'[]',true) as $option)<small>{{ $option['group']??'' }}: {{ $option['name']??'' }}</small>@endforeach</div>@endforeach</div>
