@elseif($lane==='scheduled')<p class="ops-scheduled">Iniciar a partir de {{ Illuminate\Support\Carbon::parse($order->prepare_at,'UTC')->timezone($order->scheduled_timezone??'America/Sao_Paulo')->format('d/m H:i') }}</p>
